let textoDaIA = $json.estrutura_parametros;
let listaDeCapitulos = [];

try {
  listaDeCapitulos = typeof textoDaIA === 'string' ? JSON.parse(textoDaIA) : textoDaIA;
} catch(e) {
  const erro = e instanceof Error ? e.message : String(e);
  console.log("Erro ao abrir a caixa de capítulos:", erro);
}

return {
  json: {
    capitulos_prontos: listaDeCapitulos
  }
};
